package com.starlight.greetings.web;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.ArgumentMatchers.*;import static org.mockito.BDDMockito.given;import java.util.List;
@WebMvcTest(LetterController.class) @Import(ApiExceptionHandler.class) class LetterControllerTest {@Autowired MockMvc mvc;@MockBean JdbcTemplate jdbc;@Test void unknownLetterReturnsNotFound()throws Exception{given(jdbc.query(anyString(),any(org.springframework.jdbc.core.RowMapper.class),any())).willReturn(List.of());mvc.perform(get("/api/v1/letters/unknown")).andExpect(status().isNotFound());}}
